GimCorpus.put(455,0,[[1,18,"כשם שאומדין וכו' ישבע כו'. א\"א יפה אמר ומה במקום שאין העדים יודעים אם חבל בו בעל הבית או חבל הוא בעצמו אמרו נשבע ונוטל לפי שאין דרך שיחבל אדם בעצמו והולכין אחר החזקות כיון שראו עדים שחבל בו ואין דרך אבן קטנה לחבלה כזאת לא כ\"ש עכ\"ל:",1,0],[2,2,"במקום שאינו נראה וכו'. א\"א שלא במקום רואין עכ\"ל:",1,0],[2,2,"הכהו במטפחת וכו'. א\"א במקום רואין עכ\"ל:",2,0],[2,13,"אין מוציאין מידו. כתב הראב\"ד ז\"ל פירש בעל ההלכות דמי כל אבר ואבר צער ובשת דכל אחד ואחד עכ\"ל:",1,0],[2,19,"דמי שבתו. א\"א אינו חייב לרפאותו עכ\"ל:",1,0],[4,2,"דמי ולדות לאשה. א\"א אין דבר זה מחוור מן הגמרא וההלכות דאפילו לרבא דאמר בשחבל בה לאחר מיתת הגר דזכיא לה איהי בגופייהו ה\"מ אשת הגר דאין לה יורשים דקיימא וקדמא איהי וזכיא בגוייהו אבל אשת ישראל שיש לה יורשים לעולם הם ליורשיו עכ\"ל:",1,0],[4,6,"דמי ולדות וכו'. א\"א לא מיחוורא הא מילתא דכר\"ש אזלא דאמר נתכוון להרוג את זה והרג את זה פטור ממיתה ואיהו גופיה פסק כחזקיה דאמר לא חילקו בו בין שוגג למזיד ובין מתכוין לשאינו מתכוין לחייבו ממון אלא לפוטרו ממון עכ\"ל:",1,0],[4,11,"נשאר בו קנין וכו'. א\"א ויש מי שסבור כותבין הרשאה וגובין עכ\"ל:",1,0],[4,12,"מי שחציו עבד וכו'. א\"א זה הדין כמשנה ראשונה אבל למשנה אחרונה אין כאן חלוקת ימים אלא או הכל לעצמו או הכל לרבו דהני ממונא נינהו ולא קנסא או כותבין הרשאה וגובין את הכל כמו שביארנו עכ\"ל:",1,0],[4,14,"וריפוי ובושת. א\"א דוקא בושת דחבלות אבל בושת דאונס ופתוי אינו חייב דהא אי בעי מסר לה למנוול ומוכה שחין (והכי איתא בכתובות) עכ\"ל:",1,0],[4,16,"שמרפא כל חליה. א\"א תימה הוא למה הורו שישלם הכל הרי הוא נוטל בשל אחרים שליש או שני שלישים וכשחבל בה הוא למה ישלם הכל. ואולי טעה בדבריהם שלא אמרו אלא על מה שראוי לה וקנסו אותו שלא יאכל מהם פירות דבמקום פסידא לא תקון רבנן והוא עושה שלא כהוגן דין הוא שלא יהא חוטא נשכר עכ\"ל:",1,0],[4,19,"עד שיגדילו וכו'. א\"א אפילו מציאתם שלו היא עכ\"ל:",1,0],[4,22,"הניח גחלת על לב עבדו. א\"א כפות:",1,0],[4,22,"של חבירו וכו'. א\"א בפני חבירו:",2,0],[5,4,"קנס קנסו וכו'. א\"א לא היה קנס אלא שאין דרך בני אדם לחבל בעצמן ע\"כ האמינוהו לזה בשבועה עכ\"ל:",1,0],[5,6,"הודה החובל וכו'. א\"א לא ידעתי למה פטור מאלו ואולי יאמר מפני שצריך אומדנא וזה אע\"פ שמודה לו בחבלה אינו יודע באומד לפיכך פטור מהם אבל השבת והריפוי שהם נראים לעין חייב ואינו מחוור שהכל צריך אומד הילכך חייב בכל או פטור מן הכל עכ\"ל:",1,0],[5,7,"שביישה אותו וכו'. א\"א סוף דבר דינא דגיתי הוא זה עכ\"ל:",1,0],[6,3,"שלא בכוונה פטור. א\"א דין זה אינו מחוור דאפילו שניהם ברשות (או שלא ברשות) ולא הוה [ידע] ביה אם הזיקו חייבין אבל הוזקו זה בזה פטורין עכ\"ל:",1,0],[6,4,"וכן כל כיוצא בזה וכו'. כתוב בקצת ספרי ההשגות א\"א תמה אני מאי שנא אונס זה מרוח שאינה מצויה ומן הישן ובגמרא משמע דלא איתלע אונס דאי איתלע לאו אונס עכ\"ל:",1,0],[6,5,"פטור עליהן וכו'. א\"א אפשר לדין זה כשלא נתן לו רשות למלאות אבל נתן לו רשות למלאות חייב עכ\"ל:",1,0],[7,4,"הכהנים שפגלו וכו'. א\"א במאי דאמר במזיד חייבים לשלם שיבוש הוא שאפילו עשה מעשה בגופן למאן דאמר היזק שאינו ניכר לא שמיה היזק פטור מדיני אדם אפילו במזיד וקי\"ל כוותיה וטעמא דמילתא משום דאין מתכוין להזיק אלא להנאתו הוא מתכוין משום הכי לא קנסו בו מזיד עכ\"ל:",1,0],[7,6,"לא נאסר היין וכו'. א\"א לצעורי קא מיכוין עכ\"ל:",1,0],[7,7,"גרם לו שישבר וכו'. א\"א הרב פסק כן משום דדיינינן דינא דגרמי ואין הכל מודין לו לפי שלא עשה בכלי מעשה עכ\"ל:",1,0],[7,7,"וכן כל כיוצא בזה. א\"א לא ראיתי שיבוש כזה הזורק לעולם פטור דפסיקי גיריה והמסלק אם כדברי הרב חייב ואם כדברי אחרים פטור כדכתיבנא עכ\"ל:",2,0],[7,8,"הזורק חייב וכו'. א\"א לא ראיתיו:",1,0],[7,11,"העושה עבדו אפותיקי וכו'. א\"א הרב אינו פוסק כן דרשב\"ג הוא דאית ליה הכי ורבנן פליגי עליה וקי\"ל כרבנן ולא דמי לשורף שטר חבירו דהתם בחבריה קא עביד מעשה עכ\"ל:",1,0],[7,19,"ידע המזיק וכו'. א\"א בענין הפקדון עיינתי ומה שאמר שם אינו מחוור אלא ה\"ז כאותו מעשה של שק צרור שהוא מביא לשם שנשבע ונוטל וההפרש שהוא כותב שם בין ענין זה לענין שק צרור אינו כלום דנהי דסיגין ומטכסין הוו כחטים ושעורים אבל שק ומטכסין טענו מיהא והודה לו בשק ואמר איני יודע במטכסין להוי כמודה במקצת ואיני יודע במקצת ויטול בלא שבועה אלא טעמא אחרינא אית לן בה ובין הכא ובין התם ישבע ויטול כמעשה דשק צרור עכ\"ל:",1,0],[8,4,"אנסו להביא וכו'. א\"א גם בזה ע\"ד הרב הוא הולך ואין הגאון מודה לו וכן הדין שאין לך דבר עומד בפני פיקוח נפש ומאין מתחייב לו שימות בשביל ממון חבירו הואיל וייחדו לו בפירוש וכבר הרחבנו בדברים האלו בפירוש ב\"ק עכ\"ל:",1,0],[8,15,"ספינה שחשבה וכו'. א\"א אין כאן לא מלח ולא תבלין שאין כאן דין רודף כלל ואין זה דומה למעשה דחמרא דפרק הגוזל ודין זה שהטיל איש אחד מחשבין על כולם כדאיתא בגמרא עכ\"ל:",1,0]]);
